class Solution {
public:
    int minPathCost(vector<vector<int>>& grid, vector<vector<int>>& moveCost) {
        int m = grid.size();
        int n = grid[0].size();

        vector<int> dp(n);
        for (int c = 0; c < n; c++) {
            dp[c] = grid[0][c];
        }

        for (int r = 1; r < m; r++) {
            vector<int> next(n, INT_MAX);
            for (int c = 0; c < n; c++) {
                for (int j = 0; j < n; j++) {
                    int val = grid[r - 1][j];
                    next[c] = min(next[c], dp[j] + moveCost[val][c]);
                }
                next[c] += grid[r][c];
            }
            dp = move(next);
        }

        return *min_element(dp.begin(), dp.end());
    }
};
